import { getElementSize } from '../../utils/index.js';

export const sizes = {
  width: window.innerWidth,
  height: window.innerHeight,
};
// import { sizes } from "./sizes.js";

let camera;
let renderer;
let resizeObserver;

export function resizeEventListener(
  _camera,
  _renderer,
  rootElement,
  container,
) {
  camera = _camera;
  renderer = _renderer;

  resizeObserver = new ResizeObserver(() => {
    // Update sizes
    const size = getElementSize(container || document.body);
    const renderScale = Math.min(1, Math.sqrt((1024 * 768) / (size.width * size.height)));
    console.log('================resizeEventListener', renderScale);
    console.log('resize', size, container);
    // Update camera
    camera.aspect = size.width / size.height;
    camera.updateProjectionMatrix();

    const width = size.width * renderScale;
    const height = size.height * renderScale;
    renderer.setSize(width, height);
    renderer.domElement.style.transform = `scale(${1 / renderScale})`;

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    rootElement.style.width = `${width}px`;
    rootElement.style.height = `${height}px`;
    // rootElement.style.transform = `scale(${1 / renderScale})`;
  });
  resizeObserver.observe(document.body);
}

export function clear() {
  resizeObserver.unobserve(document.body);
}
